package com.aoo.bcg.poker.cd299;

import com.aoo.bcg.gamespi.*;
import com.aoo.bcg.gamespi.time.OperationDeadline;
import com.aoo.bcg.gamespi.time.OperationDeadlineArbiter;
import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;
import java.time.Duration;
import java.util.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Server-owned真人状态机；不包含机器人、聊天、定位或支付逻辑。 */
public final class Cd299Session implements AuthoritativeGameSession {
    private static final Logger LOG=LoggerFactory.getLogger(Cd299Session.class);
    private static final List<Integer> CD299_DECK=List.of(202,402,203,104,204,304,404,105,305,106,206,306,406,107,207,307,407,108,208,308,408,109,309,110,210,310,410,111,311,212,412,506);
    public enum Phase { WAITING, BASE_AND_MANGO, DEALING, BETTING, ADD_CARD, SPLITTING, REVEAL, ROUND_SETTLEMENT, FINISHED }
    public enum BetAction { DROP, FOLLOW, REST, RAISE, ALL_IN }
    private final long roomId, ownerId, seed; private final Cd299Rules rules;
    private final AuthoritativeTimeSource time;
    private final Cd299HandEvaluator evaluator=new Cd299HandEvaluator();
    private final Map<Integer,Long> players=new LinkedHashMap<>(); private final Set<Integer> ready=new LinkedHashSet<>();
    private final Map<Integer,List<Integer>> hands=new LinkedHashMap<>(); private final Map<Integer,Long> scores=new LinkedHashMap<>(),carryScores=new LinkedHashMap<>();
    private final Map<Integer,Integer> committed=new LinkedHashMap<>(); private final Set<Integer> dropped=new LinkedHashSet<>(), split=new LinkedHashSet<>(),threeFlowerSeats=new LinkedHashSet<>();
    private final Map<Integer,Integer> bases=new LinkedHashMap<>(),mangos=new LinkedHashMap<>(),bets=new LinkedHashMap<>(),presetBetTypes=new LinkedHashMap<>();
    private final Map<Integer,Integer> mangoCursors=new LinkedHashMap<>();
    private final Map<Integer,Integer> winCounts=new LinkedHashMap<>(),loseCounts=new LinkedHashMap<>();
    private final Map<Integer,Long> restartCarryScores=new LinkedHashMap<>();
    private final Set<Integer> playedSeats=new LinkedHashSet<>(),roundSeats=new LinkedHashSet<>();
    private final Map<Integer,BetAction> lastBetActions=new LinkedHashMap<>(); private final Set<Integer> allInSeats=new LinkedHashSet<>();
    private final Set<String> operations=new LinkedHashSet<>(); private final Set<Integer> phaseActedSeats=new LinkedHashSet<>(); private final List<Object> events=new ArrayList<>(),replayEvents=new ArrayList<>();
    private final OperationDeadlineArbiter arbiter=new OperationDeadlineArbiter(); private Phase phase=Phase.WAITING;
    private final Map<Integer,Integer> timeoutCounts=new LinkedHashMap<>(),splitDelayCounts=new LinkedHashMap<>(); private final Set<Integer> hostingSeats=new LinkedHashSet<>();
    private final Map<Integer,Long> splitDeadlineEpochMillis=new LinkedHashMap<>();
    private final Map<Integer,Long> seatRetentionDeadlineEpochMillis=new LinkedHashMap<>();
    private OperationDeadline operationDeadline=OperationDeadline.none();
    private final List<Integer> deck=new ArrayList<>(); private int deckCursor;
    private int round,currentSeat=-1,bankerSeat=-1,betTarget,upMangoLevel,roundSettlementTriggerSeat=-1; private String lastMangoEvent="NONE"; private long stateVersion,roomStartedAtEpochMillis,roomEndsAtEpochMillis,terminalDeadlineEpochMillis,roundSettlementDeadlineEpochMillis,mangoPool; private Map<Long,Long> lastDelta=Map.of();
    public Cd299Session(long roomId,long ownerId,long seed,Cd299Rules rules){this(roomId,ownerId,seed,rules,AuthoritativeTimeSource.systemUtc());}
    Cd299Session(long roomId,long ownerId,long seed,Cd299Rules rules,AuthoritativeTimeSource time){this.roomId=roomId;this.ownerId=ownerId;this.seed=seed;this.rules=Objects.requireNonNull(rules);this.time=Objects.requireNonNull(time);}
    /** Atomically changes one authenticated spectator into a seated, auto-ready player. */
    public synchronized void sit(int seat,long playerId,String op){sit(seat,playerId,100L,op);}
    public synchronized void sit(int seat,long playerId,long carryScore,String op){
        mutating(op);
        if(seat<0||seat>=rules.maxPlayers())throw sitRejected("CD299_INVALID_SEAT",seat,playerId,op,true);
        if(carryScore<0||carryScore>1_000_000_000L)throw sitRejected("CD299_INVALID_CARRY_SCORE",seat,playerId,op,true);
        if(players.containsValue(playerId))throw sitRejected("CD299_ALREADY_SEATED",seat,playerId,op,false);
        if(players.containsKey(seat))throw sitRejected("CD299_SEAT_OCCUPIED",seat,playerId,op,false);
        if((phase!=Phase.WAITING&&phase!=Phase.ROUND_SETTLEMENT)||players.size()>=rules.maxPlayers())throw sitRejected("CD299_SIT_UNAVAILABLE",seat,playerId,op,false);
        boolean waiting=phase==Phase.WAITING;
        players.put(seat,playerId);carryScores.put(seat,carryScore);scores.put(seat,carryScore);winCounts.put(seat,0);loseCounts.put(seat,0);ready.add(seat);changed(op,"sit",seat);
        LOG.info("[CD299] sit accepted roomId={} playerId={} seatId={} carryScore={} operationId={} stateVersion={}",roomId,playerId,seat,carryScore,op,stateVersion);
        if(waiting&&players.size()>=rules.startPlayers())startRound();
    }
    private RuntimeException sitRejected(String code,int seat,long playerId,String op,boolean invalid){LOG.warn("[CD299] sit rejected code={} roomId={} playerId={} seatId={} operationId={} stateVersion={}",code,roomId,playerId,seat,op,stateVersion);String message="[CD299] "+code+" roomId="+roomId+" playerId="+playerId+" seatId="+seat;return invalid?new IllegalArgumentException(message):new IllegalStateException(message);}
    /** Single legacy-read bridge. New clients must send sit_req instead of ready_req. */
    private void legacyReady(int seat,long playerId,String op){sit(seat,playerId,0L,op);}
    /** XQP PREBET: a non-current player may toggle automatic REST(1) or DROP(2). */
    public synchronized void presetBet(int seat,int type,String op){mutating(op);requireSeat(seat);if(phase!=Phase.BETTING||currentSeat==seat||dropped.contains(seat)||allInSeats.contains(seat)||type<0||type>2)throw new IllegalStateException("CD299 preset bet unavailable");presetBetTypes.put(seat,type);changed(op,"presetBet:"+type,seat);}
    public synchronized void bet(int seat,BetAction action,int amount,String op){mutating(op);requireTurn(seat,Phase.BETTING);Objects.requireNonNull(action,"action");int previous=bets.getOrDefault(seat,0);long available=availableScore(seat);if(rules.eachPlayerMustFollow()&&hands.get(seat).size()==2&&previous==0&&(action==BetAction.DROP||action==BetAction.REST))throw new IllegalArgumentException("CD299 first follow required");switch(action){case DROP->dropped.add(seat);case REST->{if(!mayRest(seat))throw new IllegalArgumentException("CD299 rest unavailable");}case FOLLOW->{int value=Math.max(0,betTarget-previous);if(value>available)throw new IllegalArgumentException("CD299 cannot follow: insufficient score");bets.put(seat,previous+value);committed.merge(seat,value,Integer::sum);}case RAISE->{int minimum=minimumRaiseTarget();int value=Math.subtractExact(amount,previous);if(amount<minimum||amount<=previous||value>available)throw new IllegalArgumentException("invalid CD299 raise");bets.put(seat,amount);committed.merge(seat,value,Integer::sum);betTarget=amount;phaseActedSeats.clear();}case ALL_IN->{long allInTotal=Math.addExact(previous,available);if(allInTotal<=previous||allInTotal>Integer.MAX_VALUE)throw new IllegalArgumentException("invalid CD299 all-in");int authoritativeAmount=(int)allInTotal;int value=authoritativeAmount-previous;bets.put(seat,authoritativeAmount);committed.merge(seat,value,Integer::sum);allInSeats.add(seat);if(authoritativeAmount>betTarget){betTarget=authoritativeAmount;phaseActedSeats.clear();}}}lastBetActions.put(seat,action);changed(op,"bet:"+action,seat);advanceBetting(seat);openOperationWindow();}
    public synchronized void addCard(int seat,String op){mutating(op);requireTurn(seat,Phase.ADD_CARD);List<Integer> hand=new ArrayList<>(hands.get(seat));hand.add(drawCard());hands.put(seat,List.copyOf(hand));if(hand.size()==3&&evaluator.isThreeFlower(hand))threeFlowerSeats.add(seat);changed(op,"addCard",seat);if(activeSeats().size()<=1){phase=Phase.REVEAL;settle();return;}advanceOr(seat,hand.size()>=4?Phase.SPLITTING:Phase.BETTING);if(phase==Phase.BETTING)beginBettingPhase();else if(phase==Phase.SPLITTING)currentSeat=activeSeats().stream().filter(s->!split.contains(s)).findFirst().orElse(-1);openOperationWindow();}
    public synchronized void split(int seat,List<Integer> ordered,String op){mutating(op);requireSeat(seat);if(phase!=Phase.SPLITTING||dropped.contains(seat)||threeFlowerSeats.contains(seat)||split.contains(seat)||time.epochMillis()>=splitDeadlineEpochMillis.getOrDefault(seat,0L)||!sameCards(hands.get(seat),ordered))throw new IllegalArgumentException("invalid CD299 split");hands.put(seat,List.copyOf(ordered));split.add(seat);splitDeadlineEpochMillis.remove(seat);changed(op,"split",seat);if(split.containsAll(activeSeats())){phase=Phase.REVEAL;settle();return;}currentSeat=activeSeats().stream().filter(s->!split.contains(s)).findFirst().orElse(-1);}
    /** XQP delay-split equivalent: extend only the caller's live split window and enforce the configured limit. */
    public synchronized void delaySplit(int seat,String op){mutating(op);requireSeat(seat);long deadline=splitDeadlineEpochMillis.getOrDefault(seat,0L);if(phase!=Phase.SPLITTING||split.contains(seat)||threeFlowerSeats.contains(seat)||deadline<=time.epochMillis())throw new IllegalStateException("CD299 split delay unavailable");int used=splitDelayCounts.getOrDefault(seat,0);if(used>=rules.splitExtensionLimit())throw new IllegalStateException("CD299 split delay limit reached");splitDelayCounts.put(seat,used+1);splitDeadlineEpochMillis.put(seat,Math.addExact(deadline,Duration.ofSeconds(rules.splitExtensionSeconds()).toMillis()));changed(op,"delaySplit",seat);}
    private void autoSplit(int seat,String op){mutating(op);requireSeat(seat);if(phase!=Phase.SPLITTING||split.contains(seat)||threeFlowerSeats.contains(seat))throw new IllegalStateException("CD299 auto split unavailable");hands.put(seat,legalAutoSplit(hands.get(seat)));split.add(seat);splitDeadlineEpochMillis.remove(seat);changed(op,"autoSplit",seat);if(split.containsAll(activeSeats())){phase=Phase.REVEAL;settle();return;}currentSeat=activeSeats().stream().filter(s->!split.contains(s)).findFirst().orElse(-1);}
    public synchronized void timeout(int seat,String op){
        long now=time.epochMillis();
        if(phase==Phase.ROUND_SETTLEMENT&&seat==roundSettlementTriggerSeat&&now>=roundSettlementDeadlineEpochMillis){mutating(op);changed(op,"auto-next-round",seat);startRound();return;}
        long seatDeadline=seatRetentionDeadlineEpochMillis.getOrDefault(seat,0L);
        if(seatDeadline>0&&now>=seatDeadline){mutating(op);changed(op,"seat-retention-expired",seat);removeSeatState(seat);LOG.info("[CD299] depleted seat expired roomId={} seatId={} operationId={} stateVersion={}",roomId,seat,op,stateVersion);return;}
        boolean splitExpired=phase==Phase.SPLITTING&&now>=splitDeadlineEpochMillis.getOrDefault(seat,Long.MAX_VALUE);if(!splitExpired&&(!operationDeadline.open()||operationDeadline.seatId()!=seat||!operationDeadline.expired(time)))throw new IllegalStateException("no expired matching CD299 operation deadline");int count=timeoutCounts.merge(seat,1,Integer::sum);if(count>=rules.autoOperateAfterTimeouts())hostingSeats.add(seat);LOG.info("[CD299] operation timeout roomId={} playerId={} seatId={} operationId={} stateVersion={} timeoutCount={} hosting={}",roomId,players.get(seat),seat,op,stateVersion,count,hostingSeats.contains(seat));switch(phase){case BETTING->{boolean mustFollow=rules.eachPlayerMustFollow()&&hands.get(seat).size()==2&&bets.getOrDefault(seat,0)==0;if(mustFollow)bet(seat,Math.max(0,betTarget-bets.getOrDefault(seat,0))<=availableScore(seat)?BetAction.FOLLOW:BetAction.ALL_IN,0,op);else if(mayRest(seat))bet(seat,BetAction.REST,0,op);else bet(seat,BetAction.DROP,0,op);}case SPLITTING->autoSplit(seat,op);default->throw new IllegalStateException("no CD299 timeout action");}}
    private void startRound(){
        long now=time.epochMillis();
        if(roomStartedAtEpochMillis==0){roomStartedAtEpochMillis=now;roomEndsAtEpochMillis=now+Duration.ofMinutes(rules.roomDurationMinutes()).toMillis();}
        if(round>=rules.roundLimit()||now>=roomEndsAtEpochMillis){finishRoom();return;}
        roundSettlementDeadlineEpochMillis=0;
        roundSettlementTriggerSeat=-1;
        roundSeats.clear();
        for(int seat:players.keySet())if(round==0||scores.getOrDefault(seat,0L)>Math.addExact(1L,requiredMango(seat)))roundSeats.add(seat);
        if(roundSeats.size()<2){finishRoom();return;}
        bankerSeat=nextBankerSeat(roundSeats);
        round++;hands.clear();committed.clear();bases.clear();mangos.clear();bets.clear();presetBetTypes.clear();lastBetActions.clear();allInSeats.clear();splitDelayCounts.clear();splitDeadlineEpochMillis.clear();betTarget=0;dropped.clear();split.clear();threeFlowerSeats.clear();phaseActedSeats.clear();deck.clear();deck.addAll(CD299_DECK);Collections.shuffle(deck,new Random(seed+round));deckCursor=0;
        for(int seat:roundSeats){int mango=requiredMango(seat);int openingCommit=Math.addExact(1,mango);if(scores.getOrDefault(seat,0L)<=openingCommit)continue;bases.put(seat,1);mangos.put(seat,mango);committed.put(seat,openingCommit);playedSeats.add(seat);hands.put(seat,List.of(drawCard(),drawCard()));}
        roundSeats.retainAll(hands.keySet());if(roundSeats.size()<2){finishRoom();return;}events.add(Map.of("type","deal","stateVersion",stateVersion+1,"bankerSeat",bankerSeat));beginBettingPhase();stateVersion++;openOperationWindow();LOG.info("[CD299] round banker selected roomId={} roundNo={} bankerSeat={} bankerPlayerId={} stateVersion={}",roomId,round,bankerSeat,players.get(bankerSeat),stateVersion);
    }
    /** First round is random; later rounds rotate to the next occupied seat counterclockwise. */
    private int nextBankerSeat(Set<Integer> eligible){List<Integer>seats=eligible.stream().sorted().toList();if(seats.isEmpty())return -1;if(round==0||bankerSeat<0)return seats.get(new Random(seed^roomStartedAtEpochMillis).nextInt(seats.size()));for(int index=seats.size()-1;index>=0;index--){int seat=seats.get(index);if(seat<bankerSeat)return seat;}return seats.getLast();}
    private void finishRoom(){openTerminalRetention();stateVersion++;LOG.info("[CD299] terminal retention opened roomId={} roundNo={} stateVersion={} deadlineEpochMillis={} playerCount={}",roomId,round,stateVersion,terminalDeadlineEpochMillis,players.size());}
    /** Initializes the single authoritative terminal window without owning the caller's version transition. */
    private void openTerminalRetention(){phase=Phase.FINISHED;currentSeat=-1;operationDeadline=OperationDeadline.none();restartCarryScores.clear();terminalDeadlineEpochMillis=Math.addExact(time.epochMillis(),Duration.ofSeconds(rules.seatRetentionSeconds()).toMillis());}
    private void restart(int seat,long playerId,long carryScore,String op){
        terminalMutation(seat,playerId,carryScore,op);restartCarryScores.put(seat,carryScore);changed(op,"restart-ready",seat);
        LOG.info("[CD299] terminal continue accepted roomId={} playerId={} seatId={} carryScore={} operationId={} stateVersion={} readyCount={}",roomId,playerId,seat,carryScore,op,stateVersion,restartCarryScores.size());
        if(restartCarryScores.size()<rules.startPlayers())return;
        Set<Integer>retained=new LinkedHashSet<>(restartCarryScores.keySet());
        players.keySet().removeIf(s->!retained.contains(s));ready.retainAll(retained);carryScores.keySet().retainAll(retained);scores.keySet().retainAll(retained);winCounts.keySet().retainAll(retained);loseCounts.keySet().retainAll(retained);
        restartCarryScores.forEach((s,value)->{carryScores.put(s,value);scores.put(s,value);winCounts.put(s,0);loseCounts.put(s,0);});
        resetRoomSeries();startRound();
    }
    private void rebuy(int seat,long playerId,long carryScore,String op){mutating(op);if(players.get(seat)==null||players.get(seat)!=playerId)throw new IllegalArgumentException("[CD299] authenticated seat mismatch");long deadline=seatRetentionDeadlineEpochMillis.getOrDefault(seat,0L);if(phase!=Phase.ROUND_SETTLEMENT||deadline<=0||time.epochMillis()>=deadline||carryScore<=0||carryScore>1_000_000_000L)throw new IllegalStateException("[CD299] rebuy unavailable");carryScores.put(seat,carryScore);scores.put(seat,carryScore);seatRetentionDeadlineEpochMillis.remove(seat);if(fundedSeatCount()>=rules.startPlayers()){roundSettlementTriggerSeat=players.keySet().stream().filter(s->!seatRetentionDeadlineEpochMillis.containsKey(s)).min(Integer::compareTo).orElse(seat);roundSettlementDeadlineEpochMillis=Math.addExact(time.epochMillis(),500L);}changed(op,"rebuy",seat);LOG.info("[CD299] depleted seat rebuy accepted roomId={} playerId={} seatId={} carryScore={} operationId={} stateVersion={}",roomId,playerId,seat,carryScore,op,stateVersion);}
    private void stand(int seat,long playerId,String op){if(players.get(seat)==null||players.get(seat)!=playerId)throw new IllegalArgumentException("[CD299] authenticated seat mismatch");if(phase!=Phase.WAITING&&phase!=Phase.ROUND_SETTLEMENT&&phase!=Phase.FINISHED)throw new IllegalStateException("[CD299] stand unavailable during active hand");if(phase==Phase.FINISHED)terminalMutation(seat,playerId,0L,op);else mutating(op);changed(op,"stand",seat);removeSeatState(seat);LOG.info("[CD299] stand accepted roomId={} playerId={} seatId={} operationId={} phase={} stateVersion={} playerCount={}",roomId,playerId,seat,op,phase,stateVersion,players.size());}
    /** A terminal leave removes every authority projection for that seat before the response is built. */
    private void removeSeatState(int seat){players.remove(seat);ready.remove(seat);carryScores.remove(seat);scores.remove(seat);winCounts.remove(seat);loseCounts.remove(seat);restartCarryScores.remove(seat);seatRetentionDeadlineEpochMillis.remove(seat);hands.remove(seat);committed.remove(seat);bases.remove(seat);mangos.remove(seat);bets.remove(seat);presetBetTypes.remove(seat);mangoCursors.remove(seat);lastBetActions.remove(seat);timeoutCounts.remove(seat);splitDelayCounts.remove(seat);splitDeadlineEpochMillis.remove(seat);dropped.remove(seat);split.remove(seat);threeFlowerSeats.remove(seat);playedSeats.remove(seat);roundSeats.remove(seat);phaseActedSeats.remove(seat);allInSeats.remove(seat);hostingSeats.remove(seat);}
    private void terminalMutation(int seat,long playerId,long carryScore,String op){if(op==null||op.isBlank()||operations.contains(op)||phase!=Phase.FINISHED)throw new IllegalStateException("[CD299] terminal action unavailable");if(players.get(seat)==null||players.get(seat)!=playerId)throw new IllegalArgumentException("[CD299] authenticated seat mismatch");if(time.epochMillis()>=terminalDeadlineEpochMillis)throw new IllegalStateException("[CD299] terminal retention expired");if(carryScore<0||carryScore>1_000_000_000L)throw new IllegalArgumentException("[CD299] invalid carry score");}
    private void resetRoomSeries(){round=0;roomStartedAtEpochMillis=0;roomEndsAtEpochMillis=0;terminalDeadlineEpochMillis=0;roundSettlementDeadlineEpochMillis=0;roundSettlementTriggerSeat=-1;mangoPool=0;upMangoLevel=0;lastMangoEvent="NONE";lastDelta=Map.of();playedSeats.clear();roundSeats.clear();hands.clear();committed.clear();bases.clear();mangos.clear();bets.clear();presetBetTypes.clear();mangoCursors.clear();lastBetActions.clear();allInSeats.clear();dropped.clear();split.clear();threeFlowerSeats.clear();phaseActedSeats.clear();timeoutCounts.clear();splitDelayCounts.clear();hostingSeats.clear();splitDeadlineEpochMillis.clear();seatRetentionDeadlineEpochMillis.clear();deck.clear();deckCursor=0;betTarget=0;currentSeat=-1;bankerSeat=-1;restartCarryScores.clear();phase=Phase.WAITING;operationDeadline=OperationDeadline.none();}
    private void beginBettingPhase(){phase=Phase.BETTING;phaseActedSeats.clear();lastBetActions.clear();int cards=activeSeats().isEmpty()?2:hands.get(activeSeats().getFirst()).size();int previousMax=bets.values().stream().mapToInt(Integer::intValue).max().orElse(0);betTarget=cards<=2?rules.openingBet():Math.multiplyExact(Math.max(1,previousMax),2);for(int seat:threeFlowerSeats)if(!dropped.contains(seat)&&!allInSeats.contains(seat)){phaseActedSeats.add(seat);lastBetActions.put(seat,BetAction.REST);}currentSeat=activeSeats().stream().filter(s->!allInSeats.contains(s)&&!threeFlowerSeats.contains(s)).findFirst().orElse(-1);applyPresetIfPossible();if(currentSeat<0&&shouldAutoDealAfterAllIn(activeSeats()))autoDealToSplit(activeSeats());}
    private void applyPresetIfPossible(){while(phase==Phase.BETTING&&currentSeat>=0){int type=presetBetTypes.getOrDefault(currentSeat,0);if(type==0)break;if(type==1&&mayRest(currentSeat)){presetBetTypes.put(currentSeat,0);bet(currentSeat,BetAction.REST,0,"auto-prebet-"+round+"-"+stateVersion+"-"+currentSeat);}else if(type==2){presetBetTypes.put(currentSeat,0);bet(currentSeat,BetAction.DROP,0,"auto-prebet-"+round+"-"+stateVersion+"-"+currentSeat);}else break;}}
    private boolean mayRest(int seat){if(hands.get(seat).size()==2&&!rules.firstRoundCanRest())return false;List<Integer>acted=new ArrayList<>(phaseActedSeats);for(int i=acted.size()-1;i>=0;i--){int prior=acted.get(i);if(dropped.contains(prior))continue;return lastBetActions.get(prior)==BetAction.REST;}return true;}
    private long availableScore(int seat){return Math.max(0L,scores.getOrDefault(seat,0L)-committed.getOrDefault(seat,0));}
    private void advanceBetting(int actedSeat){phaseActedSeats.add(actedSeat);List<Integer>active=activeSeats();if(active.size()<=1){phase=Phase.REVEAL;boolean beat=rules.beatMango()&&!active.isEmpty()&&hands.values().stream().allMatch(hand->hand.size()==2)&&lastBetActions.get(active.getFirst())!=BetAction.REST;if(beat)raiseMango("BEAT");settle(beat);return;}boolean allRest=active.stream().allMatch(s->phaseActedSeats.contains(s)&&lastBetActions.get(s)==BetAction.REST);if(allRest){phase=Phase.REVEAL;if(rules.restMango())settleRestMango();else settleRestWithoutMango();return;}if(shouldAutoDealAfterAllIn(active)){autoDealToSplit(active);return;}List<Integer>remaining=active.stream().filter(s->!allInSeats.contains(s)&&!threeFlowerSeats.contains(s)).filter(s->!phaseActedSeats.contains(s)||bets.getOrDefault(s,0)<betTarget).toList();if(remaining.isEmpty()){if(active.stream().allMatch(seat->hands.get(seat).size()>=4))beginSplitting(active);else dealNextCardRound(active);return;}currentSeat=remaining.stream().filter(s->s>actedSeat).findFirst().orElse(remaining.getFirst());applyPresetIfPossible();}
    /** XQP addPoker(1): a closed betting round makes the server deal one card to every survivor. */
    private void dealNextCardRound(List<Integer> active){phase=Phase.ADD_CARD;phaseActedSeats.clear();for(int seat:active){List<Integer>hand=new ArrayList<>(hands.get(seat));if(hand.size()<4){hand.add(drawCard());hands.put(seat,List.copyOf(hand));}if(hand.size()>=3&&evaluator.isThreeFlower(hand))threeFlowerSeats.add(seat);}lastBetActions.clear();beginBettingPhase();}
    /** XQP checkOver/addPoker(Integer.MAX_VALUE): all-in closes action and deals every survivor to four cards. */
    private boolean shouldAutoDealAfterAllIn(List<Integer> active){
        if(allInSeats.isEmpty())return false;
        List<Integer>nonAllIn=active.stream().filter(s->!allInSeats.contains(s)).toList();
        if(nonAllIn.isEmpty())return true;
        int maxAllIn=allInSeats.stream().filter(active::contains).mapToInt(s->bets.getOrDefault(s,0)).max().orElse(0);
        return nonAllIn.size()==1&&bets.getOrDefault(nonAllIn.getFirst(),0)>=maxAllIn;
    }
    private void autoDealToSplit(List<Integer> active){
        for(int seat:active){
            List<Integer>hand=new ArrayList<>(hands.get(seat));
            while(hand.size()<4){hand.add(drawCard());if(hand.size()==3&&evaluator.isThreeFlower(hand))threeFlowerSeats.add(seat);}
            hands.put(seat,List.copyOf(hand));
        }
        phaseActedSeats.clear();
        List<Integer>splitCandidates=activeSeats();
        if(splitCandidates.isEmpty()){phase=Phase.REVEAL;settle();return;}
        beginSplitting(splitCandidates);
    }
    private void beginSplitting(List<Integer> candidates){phase=Phase.SPLITTING;operationDeadline=OperationDeadline.none();long deadline=Math.addExact(time.epochMillis(),Duration.ofSeconds(rules.splitSeconds()).toMillis());for(int seat:candidates){if(threeFlowerSeats.contains(seat)){split.add(seat);continue;}splitDeadlineEpochMillis.put(seat,deadline);}if(split.containsAll(activeSeats())){phase=Phase.REVEAL;settle();return;}currentSeat=candidates.stream().filter(s->!split.contains(s)).findFirst().orElse(-1);}
    private List<Integer> legalAutoSplit(List<Integer> cards){for(int a=0;a<cards.size();a++)for(int b=a+1;b<cards.size();b++){List<Integer>ordered=new ArrayList<>();ordered.add(cards.get(a));ordered.add(cards.get(b));for(int i=0;i<cards.size();i++)if(i!=a&&i!=b)ordered.add(cards.get(i));try{evaluator.split(ordered,rules.earthNineKing());return List.copyOf(ordered);}catch(IllegalArgumentException ignored){}}throw new IllegalStateException("CD299 has no legal split");}
    private void settle(){settle(false);}
    private void settle(boolean keepRaisedMango){List<Cd299SettlementEngine.Player>input=new ArrayList<>();for(int seat:roundSeats){long playerId=players.get(seat);boolean drop=dropped.contains(seat),flower=threeFlowerSeats.contains(seat)||evaluator.isThreeFlower(hands.get(seat));Cd299HandEvaluator.SplitRank rank=drop||flower||hands.get(seat).size()!=4?null:evaluator.split(hands.get(seat),rules.earthNineKing());input.add(new Cd299SettlementEngine.Player(seat,playerId,bases.getOrDefault(seat,1),mangos.getOrDefault(seat,rules.mangoScore()),bets.getOrDefault(seat,0),drop,flower,rank));}Cd299SettlementEngine.Result result=new Cd299SettlementEngine().settle(input,rules.headBigKeepsBase(),mangoPool);mangoPool=result.mangoPool();if(!keepRaisedMango)clearRaisedMango();completeSettlement(result.scoreDelta());}
    private void settleRestMango(){raiseMango("REST");Map<Long,Long>delta=new LinkedHashMap<>();long contributed=0;for(int seat:roundSeats){long mango=mangos.getOrDefault(seat,rules.mangoScore());delta.put(players.get(seat),-mango);contributed=Math.addExact(contributed,mango);}mangoPool=Math.addExact(mangoPool,contributed);completeSettlement(delta);}
    private void settleRestWithoutMango(){lastMangoEvent="REST_NO_RAISE";completeSettlement(roundSeats.stream().collect(java.util.stream.Collectors.toMap(players::get,s->0L,(a,b)->a,LinkedHashMap::new)));}
    private void raiseMango(String event){lastMangoEvent=event;if(rules.mangoRaise()>0)upMangoLevel=Math.min(rules.mangoRaise(),upMangoLevel+1);roundSeats.forEach(seat->mangoCursors.put(seat,Math.max(0,upMangoLevel-1)));}
    private void clearRaisedMango(){upMangoLevel=0;lastMangoEvent="NONE";mangoCursors.clear();}
    private int requiredMango(int seat){int base=rules.mangoScore();if(upMangoLevel<=0)return base;long total=0;int cursor=mangoCursors.getOrDefault(seat,0),end=rules.everyHandMango()?upMangoLevel:upMangoLevel-1;for(int level=cursor;level<end;level++){int n=Math.min(level+1,rules.mangoRaise());total=Math.addExact(total,rules.flipMode()==Cd299Rules.FlipMode.LADDER?Math.multiplyExact((long)base,n+1):Math.multiplyExact((long)base,1L<<n));}if(rules.everyHandMango()&&!playedSeats.contains(seat))total=Math.addExact(total,base);if(total>Integer.MAX_VALUE)throw new IllegalStateException("CD299 mango exceeds integer range");return(int)total;}
    private void completeSettlement(Map<Long,Long>delta){delta.forEach((playerId,value)->{int seat=players.entrySet().stream().filter(e->e.getValue().equals(playerId)).findFirst().orElseThrow().getKey();scores.put(seat,scores.get(seat)+value);if(value>0)winCounts.merge(seat,1,Integer::sum);else if(value<0)loseCounts.merge(seat,1,Integer::sum);});lastDelta=Map.copyOf(delta);long now=time.epochMillis();players.keySet().forEach(seat->{if(scores.getOrDefault(seat,0L)<=0)seatRetentionDeadlineEpochMillis.putIfAbsent(seat,Math.addExact(now,Duration.ofSeconds(rules.seatRetentionSeconds()).toMillis()));else seatRetentionDeadlineEpochMillis.remove(seat);});boolean terminal=round>=rules.roundLimit()||now>=roomEndsAtEpochMillis;if(terminal)openTerminalRetention();else{phase=Phase.ROUND_SETTLEMENT;currentSeat=-1;operationDeadline=OperationDeadline.none();roundSettlementTriggerSeat=fundedSeatCount()>=rules.startPlayers()?players.keySet().stream().filter(seat->!seatRetentionDeadlineEpochMillis.containsKey(seat)).min(Integer::compareTo).orElse(-1):-1;roundSettlementDeadlineEpochMillis=roundSettlementTriggerSeat<0?0:Math.addExact(now,2_000L);}splitDeadlineEpochMillis.clear();stateVersion++;LOG.info("[CD299] settlement completed roomId={} roundNo={} roundLimit={} stateVersion={} phase={} nextRoundDeadlineEpochMillis={} nextRoundTriggerSeat={} depletedSeats={} terminalDeadlineEpochMillis={} mangoPool={} playerCount={}",roomId,round,rules.roundLimit(),stateVersion,phase,roundSettlementDeadlineEpochMillis,roundSettlementTriggerSeat,seatRetentionDeadlineEpochMillis.keySet(),terminalDeadlineEpochMillis,mangoPool,players.size());}
    private long fundedSeatCount(){return players.keySet().stream().filter(seat->!seatRetentionDeadlineEpochMillis.containsKey(seat)).count();}
    private void openOperationWindow(){if(phase==Phase.SPLITTING){operationDeadline=OperationDeadline.none();return;}int seat=currentSeat;if(seat<0){operationDeadline=OperationDeadline.none();return;}operationDeadline=OperationDeadline.open("cd299:"+roomId+":"+(stateVersion+1)+":"+phase.name()+":"+seat,seat,Duration.ofSeconds(rules.operationSeconds()),time);}
    private int drawCard(){if(deckCursor>=deck.size())throw new IllegalStateException("CD299 deck exhausted");return deck.get(deckCursor++);}
    /**
     * Advances within one operation phase without inferring wraparound from the
     * current active-seat list. DROP and three-flower can remove the acting seat,
     * so comparing the next seat with the first active seat would end the phase early.
     */
    private void advanceOr(int actedSeat,Phase next){
        phaseActedSeats.add(actedSeat);
        List<Integer> active=activeSeats();
        List<Integer> remaining=active.stream().filter(s->!phaseActedSeats.contains(s)).toList();
        if(remaining.isEmpty()){
            phase=next;
            phaseActedSeats.clear();
            currentSeat=active.isEmpty()?-1:active.get(0);
            return;
        }
        currentSeat=remaining.stream().filter(s->s>actedSeat).findFirst().orElse(remaining.get(0));
    }
    private List<Integer>activeSeats(){return roundSeats.stream().filter(s->!dropped.contains(s)).sorted().toList();}
    private void requireTurn(int seat,Phase expected){requireSeat(seat);if(phase!=expected||currentSeat!=seat)throw new IllegalStateException("not CD299 turn");}
    private void requireSeat(int seat){if(!players.containsKey(seat))throw new IllegalArgumentException("unknown CD299 seat");}
    private void mutating(String op){if(op==null||op.isBlank()||operations.contains(op)||phase==Phase.FINISHED)throw new IllegalStateException("invalid/duplicate CD299 operation");}
    private void changed(String op,String type,int seat){operations.add(op);events.add(Map.of("operationId",op,"type",type,"seat",seat,"stateVersion",stateVersion+1));stateVersion++;LOG.info("[CD299] state changed roomId={} playerId={} seatId={} operationId={} action={} phase={} stateVersion={}",roomId,players.get(seat),seat,op,type,phase,stateVersion);}
    private static boolean sameCards(List<Integer>a,List<Integer>b){return a!=null&&b!=null&&a.size()==b.size()&&new HashSet<>(a).equals(new HashSet<>(b));} private static long longValue(Integer v){return v==null?0:v.longValue();}
    public synchronized GameCommandResult execute(GameCommandRequest r){
        if(r.roomId()!=roomId||!r.playVersion().equals(Cd299Rules.VERSION))throw new IllegalArgumentException("CD299 identity mismatch");
        Map<String,Object>b=r.body().asMap();long playerId=Long.parseLong(r.authenticatedUserId());
        switch(r.msgId()){
            case"poker.cd299.state_req"->{return new GameCommandResult("poker.cd299.state_rsp",r.requestId(),viewFor(playerId)).withAuthorityMetadata(stateVersion,Math.max(1,stateVersion));}
            case"poker.cd299.sit_req"->sit(number(b,"seatId",-1),playerId,requiredLong(b,"carryScore"),r.requestId());
            case"poker.cd299.ready_req"->legacyReady(number(b,"seatId",r.seatId()),playerId,r.requestId());
            case"poker.cd299.continue_req"->{
                mutating(r.requestId());
                requireAuthenticatedSeat(r,playerId);
                if(phase!=Phase.ROUND_SETTLEMENT)throw new IllegalStateException("[CD299] continue rejected");
                LOG.info("[CD299] next round accepted roomId={} playerId={} seatId={} operationId={} roundNo={} stateVersion={}",roomId,playerId,r.seatId(),r.requestId(),round,stateVersion);
                changed(r.requestId(),"continue",r.seatId());
                startRound();
            }
            case"poker.cd299.restart_req"->restart(r.seatId(),playerId,requiredLong(b,"carryScore"),r.requestId());
            case"poker.cd299.rebuy_req"->rebuy(r.seatId(),playerId,requiredLong(b,"carryScore"),r.requestId());
            case"poker.cd299.stand_req"->stand(r.seatId(),playerId,r.requestId());
            case"poker.cd299.preset_req"->{requireAuthenticatedSeat(r,playerId);presetBet(r.seatId(),number(b,"betType",0),r.requestId());}
            case"poker.cd299.bet_req"->{if(requireLivePlayerOperation(r,playerId))bet(r.seatId(),BetAction.valueOf(String.valueOf(b.get("action"))),number(b,"amount",0),r.requestId());}
            case"poker.cd299.add_card_req"->{if(requireLivePlayerOperation(r,playerId))addCard(r.seatId(),r.requestId());}
            case"poker.cd299.split_req"->{requireAuthenticatedSeat(r,playerId);split(r.seatId(),intList(b.get("cards")),r.requestId());}
            case"poker.cd299.delay_split_req"->{requireAuthenticatedSeat(r,playerId);delaySplit(r.seatId(),r.requestId());}
            case"poker.cd299.timeout_req"->{requireAuthenticatedSeat(r,playerId);timeout(r.seatId(),r.requestId());}
            default->throw new IllegalArgumentException("unsupported CD299 command");
        }
        replayEvents.add(Map.of("version",stateVersion,"after",authoritativeState()));
        return new GameCommandResult(r.msgId().replace("_req","_rsp"),r.requestId(),viewFor(playerId)).withAuthorityMetadata(stateVersion,stateVersion);
    }
    private boolean requireLivePlayerOperation(GameCommandRequest request,long playerId){Long seatedPlayer=players.get(request.seatId());if(seatedPlayer==null||seatedPlayer!=playerId)throw new IllegalArgumentException("[CD299] authenticated seat mismatch");if(!operationDeadline.open()||operationDeadline.seatId()!=request.seatId())throw new IllegalStateException("[CD299] operation unavailable");if(!operationDeadline.expired(time))return true;LOG.info("[CD299] deadline linearized as timeout roomId={} playerId={} seatId={} operationId={} stateVersion={} deadlineOperationId={}",roomId,playerId,request.seatId(),request.requestId(),stateVersion,operationDeadline.operationId());timeout(request.seatId(),request.requestId());return false;}
    private void requireAuthenticatedSeat(GameCommandRequest request,long playerId){Long seatedPlayer=players.get(request.seatId());if(seatedPlayer==null||seatedPlayer!=playerId)throw new IllegalArgumentException("[CD299] authenticated seat mismatch");}
    public synchronized Map<String,Object>viewFor(long viewer){Map<Integer,List<Integer>>visible=new LinkedHashMap<>();hands.forEach((s,c)->{boolean reveal=players.get(s)==viewer||phase==Phase.REVEAL||phase==Phase.ROUND_SETTLEMENT||phase==Phase.FINISHED;List<Integer>cards=new ArrayList<>(c.size());for(int i=0;i<c.size();i++)cards.add(reveal||i>=2?c.get(i):0);visible.put(s,List.copyOf(cards));});Map<String,Object>m=new LinkedHashMap<>(authoritativeState());int viewerSeat=players.entrySet().stream().filter(e->e.getValue()==viewer).map(Map.Entry::getKey).findFirst().orElse(-1);m.put("viewerRole",viewerSeat>=0?"SEATED":"SPECTATOR");m.put("viewerSeat",viewerSeat);m.put("hands",visible);m.put("allowedBetActions",allowedBetActions(viewerSeat));m.put("followAmount",viewerSeat<0?0:Math.max(0,betTarget-bets.getOrDefault(viewerSeat,0)));m.put("minimumRaiseTarget",viewerSeat<0?0:minimumRaiseTarget());m.put("quickRaiseTargets",quickRaiseTargets(viewerSeat));m.put("viewerAvailableScore",viewerSeat<0?0:availableScore(viewerSeat));return Map.copyOf(m);}
    private List<String>allowedBetActions(int seat){if(seat<0||phase!=Phase.BETTING||currentSeat!=seat)return List.of();List<String>actions=new ArrayList<>();int previous=bets.getOrDefault(seat,0);long available=availableScore(seat);boolean firstFollowRequired=rules.eachPlayerMustFollow()&&hands.get(seat).size()==2&&previous==0;if(!firstFollowRequired)actions.add(BetAction.DROP.name());if(Math.max(0,betTarget-previous)<=available)actions.add(BetAction.FOLLOW.name());if(!firstFollowRequired&&mayRest(seat))actions.add(BetAction.REST.name());if((long)minimumRaiseTarget()-previous<=available)actions.add(BetAction.RAISE.name());if(available>0)actions.add(BetAction.ALL_IN.name());return List.copyOf(actions);}
    private int minimumRaiseTarget(){boolean raised=lastBetActions.values().stream().anyMatch(a->a==BetAction.RAISE||a==BetAction.ALL_IN);return raised?Math.multiplyExact(Math.max(1,betTarget),2):Math.max(rules.openingBet(),betTarget);}
    private List<Integer>quickRaiseTargets(int seat){if(seat<0||phase!=Phase.BETTING||currentSeat!=seat)return List.of();long mangoTotal=roundSeats.stream().mapToLong(s->mangos.getOrDefault(s,rules.mangoScore())).sum()+mangoPool;long base=Math.max(Math.max(rules.openingBet(),betTarget),mangoTotal);boolean rest=mayRest(seat);List<Integer>targets=new ArrayList<>(3);for(int exponent=1;exponent<=3;exponent++){long value=Math.multiplyExact(base,1L<<exponent);if(rest)value/=2;if(value>Integer.MAX_VALUE)throw new IllegalStateException("CD299 quick raise exceeds integer range");targets.add((int)value);}return List.copyOf(targets);}
    public synchronized Map<String,Object>authoritativeState(){
        // Win/loss totals are durable authoritative room data used by final settlement and reconnect.
        Map<String,Object>m=new LinkedHashMap<>();m.put("schemaVersion",8);m.put("gameCode",Cd299Rules.GAME_CODE);m.put("playVersion",Cd299Rules.VERSION);m.put("roomId",roomId);m.put("ownerId",ownerId);m.put("seed",seed);m.put("rules",rules.toMap());m.put("phase",phase.name());m.put("round",round);m.put("bankerSeat",bankerSeat);m.put("stateVersion",stateVersion);m.put("roomStartedAtEpochMillis",roomStartedAtEpochMillis);m.put("roomEndsAtEpochMillis",roomEndsAtEpochMillis);m.put("terminalDeadlineEpochMillis",terminalDeadlineEpochMillis);m.put("roundSettlementDeadlineEpochMillis",roundSettlementDeadlineEpochMillis);m.put("roundSettlementTriggerSeat",roundSettlementTriggerSeat);m.put("seatRetentionDeadlineEpochMillis",Map.copyOf(seatRetentionDeadlineEpochMillis));m.put("restartCarryScores",Map.copyOf(restartCarryScores));m.put("mangoPool",mangoPool);m.put("upMangoLevel",upMangoLevel);m.put("lastMangoEvent",lastMangoEvent);m.put("mangoCursors",Map.copyOf(mangoCursors));m.put("winCounts",Map.copyOf(winCounts));m.put("loseCounts",Map.copyOf(loseCounts));m.put("playedSeats",List.copyOf(playedSeats));m.put("roundSeats",List.copyOf(roundSeats));m.put("requiredMangos",players.keySet().stream().collect(java.util.stream.Collectors.toMap(s->s,this::requiredMango,(a,b)->a,LinkedHashMap::new)));m.put("betTarget",betTarget);m.put("lastBetActions",lastBetActions.entrySet().stream().collect(java.util.stream.Collectors.toMap(Map.Entry::getKey,e->e.getValue().name(),(a,b)->a,LinkedHashMap::new)));m.put("allInSeats",List.copyOf(allInSeats));m.put("operationDeadline",operationDeadline.toMap());m.put("splitDeadlineEpochMillis",Map.copyOf(splitDeadlineEpochMillis));m.put("timeoutCounts",Map.copyOf(timeoutCounts));m.put("splitDelayCounts",Map.copyOf(splitDelayCounts));m.put("hostingSeats",List.copyOf(hostingSeats));m.put("players",Map.copyOf(players));m.put("readySeats",List.copyOf(ready));m.put("hands",Map.copyOf(hands));m.put("committed",Map.copyOf(committed));m.put("droppedSeats",List.copyOf(dropped));m.put("threeFlowerSeats",List.copyOf(threeFlowerSeats));m.put("splitSeats",List.copyOf(split));m.put("carryScores",Map.copyOf(carryScores));m.put("scores",Map.copyOf(scores));m.put("bases",Map.copyOf(bases));m.put("mangos",Map.copyOf(mangos));m.put("bets",Map.copyOf(bets));m.put("presetBetTypes",Map.copyOf(presetBetTypes));m.put("operations",List.copyOf(operations));m.put("phaseActedSeats",List.copyOf(phaseActedSeats));m.put("deck",List.copyOf(deck));m.put("deckCursor",deckCursor);m.put("currentSeat",currentSeat);m.put("lastDelta",Map.copyOf(lastDelta));return Map.copyOf(m);
    }
    public long stateVersion(){return stateVersion;}public OperationDeadline operationDeadline(){return operationDeadline;}public OperationDeadlineArbiter deadlineArbiter(){return arbiter;}public List<String>invariantViolations(){List<String>v=new ArrayList<>();if(players.size()>rules.maxPlayers())v.add("too many players");if(scores.size()!=players.size())v.add("score/player mismatch");if(!carryScores.keySet().equals(players.keySet()))v.add("carry-score/player mismatch");if(!ready.equals(players.keySet()))v.add("seated/ready mismatch");if(deckCursor<0||deckCursor>deck.size())v.add("invalid deck cursor");if(phase==Phase.FINISHED&&operationDeadline.open())v.add("finished room has open deadline");if(operationDeadline.open()&&!players.containsKey(operationDeadline.seatId()))v.add("deadline seat missing");if(phase!=Phase.SPLITTING&&!splitDeadlineEpochMillis.isEmpty())v.add("split deadline outside split phase");if(!players.keySet().containsAll(splitDeadlineEpochMillis.keySet()))v.add("split deadline seat missing");return List.copyOf(v);}public SettlementPayload settlement(int roundNo,String version){if(roundNo!=round||!version.equals(Cd299Rules.VERSION)||lastDelta.isEmpty())throw new IllegalStateException("CD299 settlement unavailable");return new SettlementPayload(roomId,roundNo,version,lastDelta);}public List<Object>recordedEvents(){return List.copyOf(replayEvents);}
    public static Cd299Session restore(Map<String,Object>s){if(!Cd299Rules.GAME_CODE.equals(String.valueOf(s.get("gameCode")))||!Cd299Rules.VERSION.equals(String.valueOf(s.get("playVersion"))))throw new IllegalArgumentException("[CD299] restore identity mismatch");Cd299Session x=new Cd299Session(lng(s.get("roomId")),lng(s.get("ownerId")),lng(s.get("seed")),Cd299Rules.from(map(s.get("rules"))));x.players.clear();copyLongMap(s.get("players"),x.players);x.scores.clear();copyLongMap(s.get("scores"),x.scores);x.carryScores.clear();copyLongMap(s.get("carryScores"),x.carryScores);x.players.keySet().forEach(seat->x.carryScores.putIfAbsent(seat,0L));copyIntMap(s.get("winCounts"),x.winCounts);copyIntMap(s.get("loseCounts"),x.loseCounts);x.players.keySet().forEach(seat->{x.winCounts.putIfAbsent(seat,0);x.loseCounts.putIfAbsent(seat,0);});copyIntMap(s.get("committed"),x.committed);copyIntMap(s.get("bases"),x.bases);copyIntMap(s.get("mangos"),x.mangos);copyIntMap(s.get("bets"),x.bets);copyIntMap(s.get("presetBetTypes"),x.presetBetTypes);copyIntMap(s.get("mangoCursors"),x.mangoCursors);copyIntMap(s.get("timeoutCounts"),x.timeoutCounts);copyIntMap(s.get("splitDelayCounts"),x.splitDelayCounts);copyLongMap(s.get("splitDeadlineEpochMillis"),x.splitDeadlineEpochMillis);copyLongMap(s.get("seatRetentionDeadlineEpochMillis"),x.seatRetentionDeadlineEpochMillis);map(s.get("lastBetActions")).forEach((k,v)->x.lastBetActions.put(Integer.parseInt(k),BetAction.valueOf(String.valueOf(v))));copyHands(s.get("hands"),x.hands);x.ready.addAll(intList(s.get("readySeats")));x.dropped.addAll(intList(s.get("droppedSeats")));x.threeFlowerSeats.addAll(intList(s.get("threeFlowerSeats")));x.split.addAll(intList(s.get("splitSeats")));x.allInSeats.addAll(intList(s.get("allInSeats")));x.hostingSeats.addAll(intList(s.get("hostingSeats")));x.phaseActedSeats.addAll(intList(s.get("phaseActedSeats")));x.playedSeats.addAll(intList(s.get("playedSeats")));x.roundSeats.addAll(intList(s.get("roundSeats")));for(Object o:list(s.get("operations")))x.operations.add(String.valueOf(o));x.deck.addAll(intList(s.get("deck")));x.deckCursor=number(s,"deckCursor",0);x.currentSeat=number(s,"currentSeat",-1);x.bankerSeat=number(s,"bankerSeat",-1);x.betTarget=number(s,"betTarget",0);x.upMangoLevel=number(s,"upMangoLevel",0);x.roundSettlementTriggerSeat=number(s,"roundSettlementTriggerSeat",-1);x.lastMangoEvent=String.valueOf(s.getOrDefault("lastMangoEvent","NONE"));x.round=number(s,"round",0);x.stateVersion=lng(s.get("stateVersion"));x.roomStartedAtEpochMillis=lngOr(s.get("roomStartedAtEpochMillis"),0);x.roomEndsAtEpochMillis=lngOr(s.get("roomEndsAtEpochMillis"),0);x.terminalDeadlineEpochMillis=lngOr(s.get("terminalDeadlineEpochMillis"),0);x.roundSettlementDeadlineEpochMillis=lngOr(s.get("roundSettlementDeadlineEpochMillis"),0);copyLongMap(s.get("restartCarryScores"),x.restartCarryScores);x.mangoPool=lngOr(s.get("mangoPool"),0);x.operationDeadline=OperationDeadline.from(s.get("operationDeadline"));x.phase=Phase.valueOf(String.valueOf(s.get("phase")));copyPlayerDelta(s.get("lastDelta"),x.lastDelta=new LinkedHashMap<>());if(x.phase==Phase.ROUND_SETTLEMENT&&x.roundSettlementDeadlineEpochMillis<=0&&x.fundedSeatCount()>=x.rules.startPlayers()){x.roundSettlementTriggerSeat=x.players.keySet().stream().filter(seat->!x.seatRetentionDeadlineEpochMillis.containsKey(seat)).min(Integer::compareTo).orElse(-1);x.roundSettlementDeadlineEpochMillis=Math.addExact(x.time.epochMillis(),2_000L);LOG.info("[CD299] legacy settlement restored with auto-next deadline roomId={} roundNo={} stateVersion={} deadlineEpochMillis={} triggerSeat={}",x.roomId,x.round,x.stateVersion,x.roundSettlementDeadlineEpochMillis,x.roundSettlementTriggerSeat);}return x;}
    public static StatePayload replay(StatePayload base,List<Object>ordered){Map<String,Object>state=new LinkedHashMap<>(base.asMap());long version=lng(state.get("stateVersion"));for(Object raw:ordered){Map<String,Object>event=map(raw);long next=lng(event.get("version"));if(next<=version)throw new IllegalArgumentException("[CD299] replay version must increase");state=new LinkedHashMap<>(map(event.get("after")));if(lng(state.get("stateVersion"))!=next)throw new IllegalArgumentException("[CD299] replay event/state mismatch");version=next;}return StatePayload.copyOf(state);}
    private static int number(Map<String,Object>m,String k,int d){Object v=m.get(k);return v instanceof Number n?n.intValue():d;}private static long requiredLong(Map<String,Object>m,String k){Object v=m.get(k);if(!(v instanceof Byte||v instanceof Short||v instanceof Integer||v instanceof Long))throw new IllegalArgumentException("[CD299] missing or invalid "+k);return ((Number)v).longValue();}private static long lng(Object v){return v instanceof Number n?n.longValue():Long.parseLong(String.valueOf(v));}private static long lngOr(Object v,long d){return v==null?d:lng(v);}private static List<?>list(Object v){return v instanceof Collection<?>c?List.copyOf(c):List.of();}private static List<Integer>intList(Object v){return list(v).stream().map(x->((Number)x).intValue()).toList();}@SuppressWarnings("unchecked")private static Map<String,Object>map(Object v){Map<String,Object>m=new LinkedHashMap<>();if(v instanceof Map<?,?>raw)raw.forEach((k,n)->m.put(String.valueOf(k),n));return m;}private static void copyLongMap(Object raw,Map<Integer,Long>out){map(raw).forEach((k,v)->out.put(Integer.parseInt(k),lng(v)));}private static void copyIntMap(Object raw,Map<Integer,Integer>out){map(raw).forEach((k,v)->out.put(Integer.parseInt(k),((Number)v).intValue()));}private static void copyHands(Object raw,Map<Integer,List<Integer>>out){map(raw).forEach((k,v)->out.put(Integer.parseInt(k),List.copyOf(intList(v))));}private static void copyPlayerDelta(Object raw,Map<Long,Long>out){map(raw).forEach((k,v)->out.put(Long.parseLong(k),lng(v)));}
}
